use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/control-codegen175";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let root=Path::new(R);let audit=read(root.join("analysis.json"));let functions=read(root.join("function-differences.json"));let mut bytes=Vec::new();for v in["accepted","combined_OFF"]{let c=&audit["variants"][v];let data=fs::read(c["binary"].as_str().unwrap()).unwrap();assert_eq!(format!("{:x}",Sha256::digest(&data)),c["ELF_sha256"]);let text=fs::read_to_string(root.join(format!("{v}-sections.txt"))).unwrap();let f=text.lines().find(|l|l.split_whitespace().any(|w|w==".rodata")).unwrap().split_whitespace().collect::<Vec<_>>();let i=f.iter().position(|&s|s==".rodata").unwrap();assert_eq!(u64::from_str_radix(f[i+2],16).unwrap(),u64::from_str_radix(f[i+3],16).unwrap());bytes.push(data);}
let mut literals=Vec::new();for(a,b)in[(0xb870usize,0xb880usize),(0xb880,0xb890)]{let old=&bytes[0][a..a+16];let new=&bytes[1][b..b+16];assert_eq!(old,new);literals.push(json!({"accepted_VA":format!("{a:x}"),"OFF_VA":format!("{b:x}"),"bytes":old.iter().map(|b|format!("{b:02x}")).collect::<String>(),"equal16bytes":true}));}
let mut selected=Vec::new();for row in functions["ambiguous_names"].as_array().unwrap(){let name=row["name"].as_str().unwrap();if !name.contains("msm")&&!name.contains("inverse"){continue}let aa=row["accepted"].as_array().unwrap();let bb=row["OFF"].as_array().unwrap();let mut pairs=Vec::new();for a in aa{let start=a[0].as_u64().unwrap()as usize;let len=a[1].as_u64().unwrap()as usize;let matches=bb.iter().filter(|b|b[0]==a[0]&&b[1]==a[1]).collect::<Vec<_>>();let same_range_exists=!matches.is_empty();let exact=same_range_exists&&bytes[0][start..start+len]==bytes[1][start..start+len];pairs.push(json!({"address":start,"length":len,"same_range_exists":same_range_exists,"exact_bytes":exact}));}selected.push(json!({"name":name,"pairs":pairs}));}
let av=fs::read_to_string(root.join("grouping-accepted-normalized.asm")).unwrap();let bv=fs::read_to_string(root.join("grouping-OFF-normalized.asm")).unwrap();let al=av.lines().collect::<Vec<_>>();let bl=bv.lines().collect::<Vec<_>>();assert_eq!(al.len(),bl.len());let mut changed=Vec::new();for(a,b)in al.iter().zip(&bl){if a==b{continue}let old=a.trim().split_whitespace().collect::<Vec<_>>();let new=b.trim().split_whitespace().collect::<Vec<_>>();assert_eq!(old[0],new[0]);assert_eq!(old[1],new[1]);assert_eq!(old.len(),new.len());let old_target=old[old.len()-1];let new_target=new[new.len()-1];assert!([( "b870","b880"),("b880","b890")].contains(&(old_target,new_target)));let old_prefix=a.split("(%rip)").next().unwrap();let new_prefix=b.split("(%rip)").next().unwrap();let cut_a=old_prefix.rfind(char::is_whitespace).unwrap();let cut_b=new_prefix.rfind(char::is_whitespace).unwrap();assert_eq!(&old_prefix[..cut_a],&new_prefix[..cut_b]);assert_eq!(a.split("(%rip)").nth(1).unwrap().split('#').next(),b.split("(%rip)").nth(1).unwrap().split('#').next());changed.push(json!({"accepted":a,"OFF":b}));}
assert_eq!(changed.len(),8);let out=json!({"grouping_instructions_differ_only_in_eight_RIP_relative_literal_relocations":true,"same16byte_literal_payloads":literals,"changed_grouping_instructions":changed,"selected_ambiguous_function_range_review":selected,"static_only":true,"new_SDK_requests":0,"new_proofs":0,"not_a_runtime_or_cache_placement_causality_claim":true});fs::write(root.join("literal-review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Grouping7624-bytebody:8RIPreferencesrelocate2identical16-byteconstants; no other instruction difference. Selected inverse/MSM aliases reviewed by address ranges.");}
